    all(
        g.backend.forward_includes_kv_cache_update
        for g in self.attn_groups[id]
    )
    for id, spec in enumerate(self.kv_cache_config.kv_cache_groups)
    if not isinstance(spec.kv_cache_spec, EncoderOnlyAttentionSpec)
)
